def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    collected = [ch for ch in s if ch in vowels]                 # every vowel, in original order
    collected.reverse()
    result = []
    idx = 0
    for ch in s:
        if ch in vowels:
            result.append(collected[idx])                          # substitute the next reversed vowel
            idx += 1
        else:
            result.append(ch)                                        # consonants copied unchanged
    return ''.join(result)


