import java.util.*;

public class Main {
    String reverseVowels(String s) {
        String vowelSet = "aeiouAEIOU";
        List<Character> collected = new ArrayList<>();
        for (char ch : s.toCharArray()) {
            if (vowelSet.indexOf(ch) != -1) collected.add(ch);            // every vowel, in original order
        }
        Collections.reverse(collected);
        StringBuilder result = new StringBuilder();
        int idx = 0;
        for (char ch : s.toCharArray()) {
            if (vowelSet.indexOf(ch) != -1) {
                result.append(collected.get(idx));                          // substitute the next reversed vowel
                idx++;
            } else {
                result.append(ch);                                            // consonants copied unchanged
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        String s = "leetcode";
        Main solution = new Main();
        System.out.println(solution.reverseVowels(s));
    }
}

