def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    chars = list(s)
    left, right = 0, len(chars) - 1
    while left < right:
        if chars[left] not in vowels:
            left += 1                                              # skip consonants from the left
        elif chars[right] not in vowels:
            right -= 1                                               # skip consonants from the right
        else:
            chars[left], chars[right] = chars[right], chars[left]       # both are vowels, swap them
            left += 1
            right -= 1
    return ''.join(chars)


if __name__ == "__main__":
    s = "leetcode"
    print(reverse_vowels(s))

