        String vowelSet = "aeiouAEIOU";
        char[] chars = s.toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            if (vowelSet.indexOf(chars[left]) == -1) {
                left++;                                                    // skip consonants from the left
            } else if (vowelSet.indexOf(chars[right]) == -1) {
                right--;                                                     // skip consonants from the right
            } else {
                char temp = chars[left];
                chars[left] = chars[right];
                chars[right] = temp;                                          // both are vowels, swap them
                left++;
                right--;
            }
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        String s = "leetcode";
        Main solution = new Main();
        System.out.println(solution.reverseVowels(s));
